import {SPOTIFY_LOGIN,normalizeSpotifyLinks,addSpotifyLink,removeSpotifyLink} from './spotify-links.mjs';
export function setupSpotifyRadio(storage,onChange){const $=id=>document.getElementById(id);let state=normalizeSpotifyLinks(storage.get('spotify-links',{}));
  const selected=()=>state.stations.find(s=>s.id===state.selectedId);
  function render(){document.querySelectorAll('[data-music-source]').forEach(b=>b.setAttribute('aria-pressed',String((b.dataset.musicSource==='spotify')===state.external)));$('spotify-panel').classList.toggle('hidden',!state.external);document.querySelector('.radio-tuner').classList.toggle('hidden',state.external);$('music-source-note').textContent=state.external?'Die Spielmusik pausiert. Spotify-Wiedergabe und -Lautstärke stellst du bei Spotify ein.':'';$('music-volume').disabled=state.external;$('music-mute').disabled=state.external;
    const menu=$('spotify-station');menu.replaceChildren();if(!state.stations.length){const option=document.createElement('option');option.textContent='Noch kein Radio gespeichert';option.value='';menu.append(option);}for(const station of state.stations){const option=document.createElement('option');option.value=station.id;option.textContent=station.label;menu.append(option);}menu.value=state.selectedId;menu.disabled=!state.stations.length;$('spotify-remove').disabled=!state.stations.length;const station=selected();$('spotify-launch').hidden=!station;if(station){$('spotify-launch').href=station.url;$('spotify-launch').textContent=station.label+' bei Spotify öffnen ↗';}$('spotify-login').href=SPOTIFY_LOGIN;
  }
  function save(){storage.set('spotify-links',state);render();onChange();}
  document.querySelectorAll('[data-music-source]').forEach(b=>b.addEventListener('click',()=>{state.external=b.dataset.musicSource==='spotify';$('spotify-status').textContent='';save();}));
  $('spotify-add-form').addEventListener('submit',e=>{e.preventDefault();try{state=addSpotifyLink(state,$('spotify-url').value,$('spotify-label').value);save();$('spotify-url').value='';$('spotify-label').value='';$('spotify-status').textContent='Link gespeichert. Öffne den Mix bei Spotify und starte dort die Wiedergabe.';$('spotify-status').dataset.error='false';}catch(error){$('spotify-status').textContent=error.message;$('spotify-status').dataset.error='true';}});
  $('spotify-station').addEventListener('change',e=>{state.selectedId=e.target.value;save();$('spotify-status').textContent='Ausgewählt. Zum Abspielen bei Spotify öffnen.';});
  $('spotify-remove').addEventListener('click',()=>{state=removeSpotifyLink(state,state.selectedId);save();$('spotify-status').textContent='Link entfernt.';});
  $('spotify-launch').addEventListener('click',()=>{$('spotify-status').textContent='Spotify öffnet sich in einem eigenen Tab. Melde dich dort an und starte die Musik. Dieses Spiel kann den Wiedergabestatus nicht sehen.';});
  render();return {isExternal:()=>state.external,selectedLabel:()=>selected()?.label||'SPOTIFY EXTERN'};
}
